import{_ as a}from"./chunks/generic-square.DcUM8NPF.js";import{_ as r,o as i,c as o,a0 as l}from"./chunks/framework.FSADoC4m.js";const f=JSON.parse('{"title":"Nearby — Bang Wad Reservoir","description":"Explore more around Bang Wad Reservoir — trails, viewpoints, and local experiences.","frontmatter":{"title":"Nearby — Bang Wad Reservoir","description":"Explore more around Bang Wad Reservoir — trails, viewpoints, and local experiences."},"headers":[],"relativePath":"nearby.md","filePath":"nearby.md","lastUpdated":null}'),t={name:"nearby.md"};function n(s,e,h,p,d,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="🌿-explore-nearby" tabindex="-1">🌿 Explore Nearby <a class="header-anchor" href="#🌿-explore-nearby" aria-label="Permalink to &quot;🌿 Explore Nearby&quot;">​</a></h1><p><img src="'+a+'" alt="Bang Wad Reservoir"></p><p>Bang Wad Reservoir is more than just a place to walk.</p><p>It’s a small ecosystem of trails, viewpoints, quiet corners, and local life.</p><p>Take your time — there’s more to discover beyond each QR code.</p><hr><h2 id="🧭-around-the-reservoir" tabindex="-1">🧭 Around the Reservoir <a class="header-anchor" href="#🧭-around-the-reservoir" aria-label="Permalink to &quot;🧭 Around the Reservoir&quot;">​</a></h2><h3 id="🚶-walking-running-trail" tabindex="-1">🚶 Walking &amp; Running Trail <a class="header-anchor" href="#🚶-walking-running-trail" aria-label="Permalink to &quot;🚶 Walking &amp; Running Trail&quot;">​</a></h3><p>A full loop around the reservoir stretches for several kilometers.</p><ul><li>smooth paved sections</li><li>shaded forest paths</li><li>open dam views</li></ul><p>💡 <em>Best time: early morning or sunset</em></p><hr><h3 id="🌄-sunset-dam-view" tabindex="-1">🌄 Sunset &amp; Dam View <a class="header-anchor" href="#🌄-sunset-dam-view" aria-label="Permalink to &quot;🌄 Sunset &amp; Dam View&quot;">​</a></h3><p>One of the most popular spots.</p><ul><li>wide open view over the water</li><li>soft light reflections</li><li>calm atmosphere</li></ul><p>📸 <em>This is where many of the best photos are taken</em></p><hr><h3 id="🌿-quiet-corners" tabindex="-1">🌿 Quiet Corners <a class="header-anchor" href="#🌿-quiet-corners" aria-label="Permalink to &quot;🌿 Quiet Corners&quot;">​</a></h3><p>Step away from the main path and you’ll find:</p><ul><li>hidden benches</li><li>small clearings</li><li>shaded areas under trees</li></ul><p>💡 <em>Perfect for reading, resting, or just doing nothing</em></p><hr><h2 id="🛕-nearby-landmarks" tabindex="-1">🛕 Nearby Landmarks <a class="header-anchor" href="#🛕-nearby-landmarks" aria-label="Permalink to &quot;🛕 Nearby Landmarks&quot;">​</a></h2><h3 id="🛕-local-temple-area" tabindex="-1">🛕 Local Temple Area <a class="header-anchor" href="#🛕-local-temple-area" aria-label="Permalink to &quot;🛕 Local Temple Area&quot;">​</a></h3><p>A short ride or walk away:</p><ul><li>peaceful surroundings</li><li>traditional Thai architecture</li><li>less crowded than city temples</li></ul><hr><h3 id="⛰️-hills-forest-roads" tabindex="-1">⛰️ Hills &amp; Forest Roads <a class="header-anchor" href="#⛰️-hills-forest-roads" aria-label="Permalink to &quot;⛰️ Hills &amp; Forest Roads&quot;">​</a></h3><p>There are small roads and trails leading up into the hills.</p><ul><li>light hiking possible</li><li>natural viewpoints</li><li>more secluded atmosphere</li></ul><p>⚠️ <em>Go during daylight and stay on visible paths</em></p><hr><h2 id="🥥-local-experience" tabindex="-1">🥥 Local Experience <a class="header-anchor" href="#🥥-local-experience" aria-label="Permalink to &quot;🥥 Local Experience&quot;">​</a></h2><p>Around the reservoir, you may find:</p><ul><li>fresh coconut water</li><li>simple street food</li><li>small coffee setups</li></ul><p>Nothing formal — just part of everyday life here.</p><hr><h2 id="🌟-part-of-the-experience" tabindex="-1">🌟 Part of the Experience <a class="header-anchor" href="#🌟-part-of-the-experience" aria-label="Permalink to &quot;🌟 Part of the Experience&quot;">​</a></h2><p>Kathu Phuket Foresta is not just about plants.</p><p>It’s about:</p><ul><li>exploring the area</li><li>noticing details</li><li>slowing down</li></ul><p>👉 Each QR sign is just a starting point.</p><hr><h2 id="📸-you-can-be-part-of-it" tabindex="-1">📸 You can be part of it <a class="header-anchor" href="#📸-you-can-be-part-of-it" aria-label="Permalink to &quot;📸 You can be part of it&quot;">​</a></h2><p>This project grows through real moments.</p><p>You can contribute:</p><ul><li>photos of the area</li><li>your own perspective</li><li>hidden spots you discovered</li></ul><p>👉 <a href="https://forms.gle/A79giJZSbqgsj5BR6" target="_blank" rel="noreferrer">Submit a photo or suggestion</a></p><hr><h2 id="🌱-keep-exploring" tabindex="-1">🌱 Keep exploring <a class="header-anchor" href="#🌱-keep-exploring" aria-label="Permalink to &quot;🌱 Keep exploring&quot;">​</a></h2><ul><li><a href="/">Back to main page</a></li><li><a href="/best-photos">Best photos of the week</a></li></ul><hr><p>💡 <em>Walk a little further. You might find something unexpected.</em></p>',53)])])}const b=r(t,[["render",n]]);export{f as __pageData,b as default};
